mapper.update:
/* com.heeji.picket.mapper.PaymentMapper.done */
UPDATE  PAYMENT
SET     STATUS      = 'DONE'
,       PAYMENT_KEY = #{paymentKey}
,       PAID_DATE   = NOW()
,       METHOD      = #{method}
,       PG_CODE     = #{pgCode}
WHERE   ORDER_ID = #{orderId}
AND     STATUS = 'READY'

mapper.delete:
/* com.heeji.picket.mapper.PaymentMapper.deleteReady */
DELETE FROM PAYMENT
WHERE   ORDER_ID = #{orderId}
AND     STATUS = 'READY'

mapper.update:
/* com.heeji.picket.mapper.PaymentMapper.cancel */
UPDATE  PAYMENT
SET     STATUS        = 'CANCELED'
,       CANCELED_DATE = NOW()
,       CANCEL_REASON = #{cancelReason}
WHERE   BOOKED_NUMBER = #{bookedNumber}
AND     PAID_ID = #{userId}
AND     CANCELED_DATE IS NULL

mapper.select:
/* com.heeji.picket.mapper.PaymentMapper.myCanceled */ SELECT P.BOOKED_NUMBER AS bookedNumber , P.SHOW_ID AS showId , SH.TITLE AS title , SH.PLACE AS place , SD.SHOW_DATE AS showDate , P.SEAT_COUNT AS count , P.SEAT_NAMES AS seatNames , P.AMOUNT AS amount , P.CANCELED_DATE AS canceledDate FROM PAYMENT P LEFT JOIN SHOWS SH ON SH.SHOW_ID = P.SHOW_ID LEFT JOIN SHOW_DATE SD ON SD.SHOW_DATE_ID = P.SHOW_DATE_ID WHERE P.PAID_ID = #{userId} AND P.CANCELED_DATE IS NOT NULL
AND DATE(SD.SHOW_DATE) = #{viewDate}
AND SH.TITLE LIKE CONCAT('%', #{ticketName}, '%')
ORDER BY P.CANCELED_DATE DESC
